<template><div class="project-basic-form"><el-form ref="refForm" :model="model" label-position="top" :rules="rules" :disabled="disabled"><div class="zj-grid"><el-form-item label="项目名称" prop="projectName"><el-input v-model="model.projectName" maxlength="255"/></el-form-item><el-form-item label="所属合同" prop="contractId"><el-select v-model="model.contractId" filterable remote :remote-method="findContracts" :loading="searching" placeholder="输入合同名称或编号搜索" @visible-change="v=>v&&findContracts('')"><el-option label="待签订（暂不关联合同）" :value="0"/><el-option v-for="c in contracts" :key="c.id" :value="c.id" :label="`${c.contractName||'名称待填写'} · ${c.contractNo||'未填写编号'}`"/></el-select></el-form-item><el-form-item label="委托 / 建设单位"><el-input v-model="model.clientName" maxlength="255"/></el-form-item><el-form-item v-if="projectType!=='WB'" label="项目地址"><el-input v-model="model.siteAddress" maxlength="500"/></el-form-item><el-form-item v-if="projectType!=='WB'" label="联系人"><el-input v-model="model.contactName" maxlength="100"/></el-form-item><el-form-item v-if="projectType!=='WB'" label="联系电话"><el-input v-model="model.contactPhone" maxlength="50"/></el-form-item><el-form-item label="项目负责人"><el-select v-model="model.leaderUserId" clearable filterable remote :remote-method="findUsers" @visible-change="v=>v&&findUsers('')" placeholder="搜索公司员工"><el-option v-for="u in users" :key="u.id" :label="u.name+' ('+(u.username||u.id)+')'" :value="u.id"/></el-select></el-form-item><el-form-item label="技术负责人"><el-select v-model="model.technicalUserId" clearable filterable remote :remote-method="findUsers" @visible-change="v=>v&&findUsers('')" placeholder="搜索公司员工"><el-option v-for="u in users" :key="u.id" :label="u.name+' ('+(u.username||u.id)+')'" :value="u.id"/></el-select></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="model.startDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期"><el-button v-if="projectType==='WB'" link type="primary" :disabled="!model.startDate||disabled" @click="fillAnniversary">填入开始日期一年后</el-button><el-date-picker v-model="model.endDate" value-format="YYYY-MM-DD"/></el-form-item></div></el-form></div></template>
<script setup>
import {fileUrl} from '@/utils/files';
import {projectContracts,projectUsers} from '@/api/workProject';
const emit=defineEmits(['contract-preview']);
const model=defineModel({type:Object,required:true});const props=defineProps({projectType:String,disabled:Boolean,legacy:Boolean,previewContract:Boolean});const refForm=ref(),contracts=ref([]),users=ref([]),searching=ref(false);let contractSequence=0,userSequence=0;
const rules={projectName:[{required:true,message:'请填写项目名称',trigger:'blur'}],contractId:[{validator:(_r,v,cb)=>v!==0&&!v&&!props.legacy?cb(new Error('请选择所属合同')):cb(),trigger:'change'}]};
watch(()=>model.value, v=>{contracts.value=v.contractId?[{id:v.contractId,contractName:v.contractName||'已关联合同',contractNo:v.contractNumber}]:[];users.value=[...(v.leaderUserId?[{id:v.leaderUserId,name:v.leaderName||'已选员工'}]:[]),...(v.technicalUserId?[{id:v.technicalUserId,name:v.technicalName||'已选员工'}]:[])];},{immediate:true});
async function findContracts(name){if(props.disabled)return;const n=++contractSequence;searching.value=true;try{const r=await projectContracts({projectType:props.projectType,name,pageSize:20,pageNum:1});if(n===contractSequence)contracts.value=r.rows;}finally{if(n===contractSequence)searching.value=false;}}
async function findUsers(name){if(props.disabled)return;const n=++userSequence;const r=await projectUsers({name,pageSize:20,pageNum:1});if(n===userSequence)users.value=r.rows;}
const previewFile=ref('');const contractFiles=computed(()=>String(contracts.value.find(c=>c.id===model.value.contractId)?.contractFile||'').split(',').filter(Boolean));watch(()=>model.value.contractId,()=>previewFile.value='');watch(contractFiles,files=>emit('contract-preview',files),{immediate:true});
function fillAnniversary(){const [y,m,d]=model.value.startDate.split('-').map(Number);const last=new Date(y+1,m,0).getDate();model.value.endDate=`${y+1}-${String(m).padStart(2,'0')}-${String(Math.min(d,last)).padStart(2,'0')}`}
defineExpose({validate:()=>refForm.value.validate()});
</script>
<style scoped>.maintenance-create{display:grid;grid-template-columns:minmax(300px,1fr) minmax(300px,1fr);gap:24px}.contract-preview iframe{width:100%;height:65vh;border:1px solid #e5eaf2;margin:12px 0}.contract-preview .el-link{margin-right:12px}@media(max-width:900px){.maintenance-create{grid-template-columns:1fr}.contract-preview iframe{height:40vh}}</style>
